export const MESSAGE_TYPE = Object.freeze({
  TEXT: 'text',
  EMOJI: 'emoji',
  /** Generated by the server (auto-greeting, "coins ran out"), never by a client. */
  SYSTEM: 'system',
});

/** Messages a client is allowed to originate. Media is intentionally excluded. */
export const CLIENT_MESSAGE_TYPES = Object.freeze([MESSAGE_TYPE.TEXT, MESSAGE_TYPE.EMOJI]);

export const CONVERSATION_STATUS = Object.freeze({
  ACTIVE: 'active',
  BLOCKED: 'blocked',
  CLOSED: 'closed',
});

/**
 * A conversation between two people must be unique regardless of who opened it,
 * so the pair key is built from sorted ids.
 */
export function buildParticipantKey(userIdA, userIdB) {
  return [String(userIdA), String(userIdB)].sort().join(':');
}
